func TestGroupParity(t *testing.T) {
	testCases := []struct {
		input    []int
		expected map[string][]int
	}{
		{[]int{}, map[string][]int{"even": {}, "odd": {}}},
		{[]int{1}, map[string][]int{"even": {}, "odd": {1}}},
		{[]int{2}, map[string][]int{"even": {2}, "odd": {}},
		{[]int{1, 2, 3, 4}, map[string][]int{"even": {2, 4}, "odd": {1, 3}}},
	}

	for _, tc := range testCases {
		result := GroupParity(tc.input)
		if len(result["even"]) != len(tc.expected["even"]) || len(result["odd"]) != len(tc.expected["odd"]) {
			t.Errorf("GroupParity(%v) = %v; want %v", tc.input, result, tc.expected)
		}
		for _, v := range tc.expected["even"] {
			if !contains(result["even"], v) {
				t.Errorf("GroupParity(%v) missing even value %d", tc.input, v)
			}
		}
		for _, v := range tc.expected["odd"] {
			if !contains(result["odd"], v) {
				t.Errorf("GroupParity(%v) missing odd value %d", tc.input, v)
			}
		}
	}
}

func contains(slice []int, value int) bool {
	for _, v := range slice {
		if v == value {
			return true
		}
	}
	return false
}

