import (
	"errors"
	"fmt"
	"strconv"
	"testing"
)

// SumDigits sums the decimal digits in s, returning an error wrapping strconv via fmt.Errorf %w on a non-digit.
func SumDigits(s string) (int, error) {
	sum := 0
	for _, char := range s {
		digit, err := strconv.Atoi(string(char))
		if err != nil {
			return 0, fmt.Errorf("non-digit character: %w", err)
		}
		sum += digit
	}
	return sum, nil
}

// TestSumDigits tests the SumDigits function with various inputs.
func TestSumDigits(t *testing.T) {
	testCases := []struct {
		input    string
		expected int
	}{
		{"123", 6},
		{"456789", 45},
		{"0", 0},
		{"abc", 0},
		{"1a2b3c", 6},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Input: %s", tc.input), func(t *testing.T) {
			result, err := SumDigits(tc.input)
			if err != nil && !errors.Is(err, fmt.Errorf("non-digit character: strconv.Atoi: invalid syntax")) {
				t.Errorf("SumDigits(%q) returned an unexpected error: %v", tc.input, err)
			} else if err == nil && result != tc.expected {
				t.Errorf("SumDigits(%q) = %d; want %d", tc.input, result, tc.expected)
			}
		})
	}
}

