			ch: func() chan int {
				ch := make(chan int, 3)
				ch <- 1
				ch <- 2
				close(ch)
				return ch
			}(),
			cancel:   false,
			expected: 2,
		},
		{
			name: "channel with values and context cancel",
			ch: func() chan int {
				ch := make(chan int, 3)
				ch <- 1
				ch <- 2
				return ch
			}(),
			cancel:   true,
			expected: 1,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			ctx, cancel := context.WithCancel(context.Background())
			if tc.cancel {
				defer cancel()
			}
			result := CountUntil(ctx, tc.ch)
			if result != tc.expected {
				t.Errorf("CountUntil() = %d; want %d", result, tc.expected)
			}
		})
	}
}

