import (
	"io"
	"reflect"
	"strings"
	"testing"
)

func TestReadChunks(t *testing.T) {
	testCases := []struct {
		name     string
		reader   io.Reader
		size     int
		expected [][]byte
		err      error
	}{
		{
			name: "empty reader",
			reader: func() io.Reader {
				return io.NopCloser(strings.NewReader(""))
			}(),
			size: 10,
			expected: [][]byte{
				{},
			},
			err: nil,
		},
		{
			name: "reader with data",
			reader: func() io.Reader {
				return io.NopCloser(strings.NewReader("abcdefg"))
			}(),
			size: 3,
			expected: [][]byte{
				{97, 98, 99},    // 'a', 'b', 'c'
				{100, 101, 102}, // 'd', 'e', 'f'
				{103},           // 'g'
			},
			err: nil,
		},
		{
			name: "reader with data and size larger than chunk",
			reader: func() io.Reader {
				return io.NopCloser(strings.NewReader("abcdefg"))
			}(),
			size: 10,
			expected: [][]byte{
				{97, 98, 99, 100, 101, 102, 103}, // 'a', 'b', 'c', 'd', 'e', 'f', 'g'
			},
			err: nil,
		},
		{
			name: "reader with error",
			reader: func() io.Reader {
				return &errorReader{err: io.EOF}
			}(),
			size:     10,
			expected: [][]byte{},
			err:      io.EOF,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result, err := ReadChunks(tc.reader, tc.size)
			if !reflect.DeepEqual(result, tc.expected) {
				t.Errorf("ReadChunks(%v, %d) = %v; want %v", tc.reader, tc.size, result, tc.expected)
			}
			if err != tc.err {
				t.Errorf("ReadChunks(%v, %d) error = %v; want %v", tc.reader, tc.size, err, tc.err)
			}
		})
	}
}

type errorReader struct{ err error }

func (er *errorReader) Read(p []byte) (n int, err error) {
	return 0, er.err
}

package sandbox

import (
	"net/http"
	"testing"
)

// TestChain tests the Chain function to ensure it correctly applies middleware layers.
func TestChain(t *testing.T) {
	// Define a simple handler for testing
	testHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("Hello, World!"))
	})

	// Define middleware functions
	middleware1 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("Middleware 1: "))
			next.ServeHTTP(w, r)
		})
	}

	middleware2 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("Middleware 2: "))
			next.ServeHTTP(w, r)
		})
	}

	// Create the chained handler
	chainedHandler := Chain(testHandler, middleware1, middleware2)

	// Create a mock ResponseWriter to capture the output
	mockResponseWriter := &mockResponseWriter{}

	// Create a mock Request for testing
	req, err := http.NewRequest("GET", "/", nil)
	if err != nil {
		t.Fatal(err)
	}

	// Call the chained handler
	chainedHandler.ServeHTTP(mockResponseWriter, req)

	// Expected output: "Middleware 1: Middleware 2: Hello, World!"
	expectedOutput := "Middleware 1: Middleware 2: Hello, World!"
	actualOutput := mockResponseWriter.body.String()

	if actualOutput != expectedOutput {
		t.Errorf("Expected %s, but got %s", expectedOutput, actualOutput)
	}
}

// mockResponseWriter is a mock implementation of http.ResponseWriter for testing purposes.
type mockResponseWriter struct {
	body []byte
}

func (m *mockResponseWriter) Write(b []byte) (int, error) {
	m.body = append(m.body, b...)
	return len(b), nil
}

func (m *mockResponseWriter) Header() http.Header {
	return make(http.Header)
}

func (m *mockResponseWriter) WriteHeader(statusCode int) {}
